#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_comp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_comp(uv);return float4(0.0); }
uniform float amzp_completion;
uniform float amzp_twidth;
uniform float amzp_back;
layout(color) uniform half4 amzp_backColor;
uniform float amzp_rows;
uniform float amzp_columns;
uniform float amzp_gap;
uniform float amzp_axis;
uniform float amzp_flipDir;
uniform float amzp_order;
uniform float amzp_randomness;
uniform float amzp_seed;
uniform float amzp_perspective;
uniform float amzp_shading;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 advF(float2 uv, float2 pv) { float2 W = layer; float2 q = advRot((uv - pv) * W, radians(amzp_advAngle)) / max(amzp_advScale, 0.01); return q / W + pv; }
    float2 advI(float2 pu, float2 pv) { float2 W = layer; float2 q = advRot((pu - pv) * W * max(amzp_advScale, 0.01), -radians(amzp_advAngle)); return q / W + pv; }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.5) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float4 layerAt(float2 uv) { return inside(uv) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 belowAt(float2 uv) { return amzTexture(1, l2s(uv)); }
    float hash(float2 p, float k) {
        return fract(sin(dot(p, float2(12.9898, 78.233)) + amzp_seed * 17.137 + k * 31.71) * 43758.5453);
    }
    float orderOf(float2 cc, float2 id) {
        if (int(amzp_order) == 0) return cc.x;
        if (int(amzp_order) == 1) return 1.0 - cc.x;
        if (int(amzp_order) == 2) return cc.y;
        if (int(amzp_order) == 3) return 1.0 - cc.y;
        if (int(amzp_order) == 4) return (cc.x + cc.y) * 0.5;
        if (int(amzp_order) == 5) return (1.0 - cc.x + cc.y) * 0.5;
        if (int(amzp_order) == 6) return (cc.x + 1.0 - cc.y) * 0.5;
        if (int(amzp_order) == 7) return (2.0 - cc.x - cc.y) * 0.5;
        if (int(amzp_order) == 8) return clamp(length(cc - 0.5) / 0.7072, 0.0, 1.0);
        return hash(id, 5.0);
    }
    void amzRender() {
        float2 W = layer;
        float nc = max(1.0, floor(amzp_columns + 0.5));
        float nr = max(1.0, floor(amzp_rows + 0.5));
        float2 cell = W / float2(nc, nr);
        float2 P = advF(amzLayerNorm(), float2(0.5));
        float2 q = float2(P.x, 1.0 - P.y) * W;
        float2 base = floor(q / cell);
        float D = mix(12.0, 1.6, clamp(amzp_perspective, 0.0, 1.0)) * max(W.x, W.y);
        float tw = max(amzp_twidth, 0.001);
        float C = clamp(prog(amzp_completion), 0.0, 1.0);
        float bestZ = -1e9;
        float4 col = float4(0.0);
        bool hit = false;
        for (int j = -1; j <= 1; j++) {
            for (int i = -1; i <= 1; i++) {
                float2 id = base + float2(float(i), float(j));
                float2 cc = clamp((id + 0.5) / float2(nc, nr), 0.0, 1.0);
                float o = mix(orderOf(cc, id), hash(id, 1.0), clamp(amzp_randomness, 0.0, 1.0));
                float t = clamp((C * (1.0 + tw) - o) / tw, 0.0, 1.0);
                if (C >= 1.0) t = 1.0;
                float sgn = int(amzp_flipDir) == 1 ? -1.0 : 1.0;
                if (int(amzp_flipDir) == 2) sgn = hash(id, 2.0) < 0.5 ? -1.0 : 1.0;
                bool ax = int(amzp_axis) == 1;
                if (int(amzp_axis) == 2) ax = hash(id, 3.0) < 0.5;
                float th = t * 3.14159265 * sgn;
                float c = cos(th), s = sin(th);
                float2 hsz = cell * 0.5 - float2(amzp_gap * 0.5);
                if (hsz.x <= 0.0 || hsz.y <= 0.0) continue;
                float2 X = q - (id + 0.5) * cell;
                float Xu = ax ? X.x : X.y;
                float Xv = ax ? X.y : X.x;
                float hu = ax ? hsz.x : hsz.y;
                float hv = ax ? hsz.y : hsz.x;
                float den = hu * (c * D + Xu * s);
                if (abs(den) < 1e-6) continue;
                float u = Xu * D / den;
                float z = u * hu * s;
                float f = D / (D - z);
                if (f <= 0.0) continue;
                float v = Xv / (hv * f);
                if (abs(u) > 1.0 || abs(v) > 1.0) continue;
                if (z <= bestZ) continue;
                bool front = c >= 0.0;
                float uu = front ? u : -u;
                float2 lu = ax ? float2(uu, v) : float2(v, uu);
                float2 lm = ax ? float2(u, v) : float2(v, u);
                float2 pq = (id + 0.5) * cell + lu * hsz;
                float2 uv = advI(float2(pq.x / W.x, 1.0 - pq.y / W.y), float2(0.5));
                float2 pm = (id + 0.5) * cell + lm * hsz;
                float2 uvm = advI(float2(pm.x / W.x, 1.0 - pm.y / W.y), float2(0.5));
                if (!inside(uvm)) continue;
                float4 k;
                if (front) {
                    k = layerAt(uv);
                } else if (int(amzp_back) == 0) {
                    k = belowAt(uv);
                } else if (int(amzp_back) == 1) {
                    k = layerAt(uv);
                } else if (int(amzp_back) == 2) {
                    k = layerAt(uvm);
                } else if (int(amzp_back) == 3) {
                    k = float4(amzp_backColor.rgb, 1.0);
                } else {
                    k = float4(0.0);
                }
                float sh = mix(1.0, 0.35 + 0.65 * abs(c), clamp(amzp_shading, 0.0, 1.0));
                k.rgb *= sh;
                bestZ = z;
                col = k;
                hit = true;
            }
        }
        amzOutput = hit ? col : float4(0.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
